#!/usr/bin/env python3
"""Patch the Android project generated by `flutter create` for Daily Deen.

- app label "Daily Deen"
- notification permissions + scheduled-notification receivers
- core library desugaring (needed by flutter_local_notifications)
- release signing from android/key.properties (if present)
"""
import pathlib
import re
import sys

root = pathlib.Path(__file__).resolve().parent.parent / "android"
app = root / "app"

# ---------------- AndroidManifest ----------------
manifest = app / "src/main/AndroidManifest.xml"
m = manifest.read_text()
m = re.sub(r'android:label="[^"]*"', 'android:label="Daily Deen"', m, count=1)
perms = (
    '    <uses-permission android:name="android.permission.POST_NOTIFICATIONS"/>\n'
    '    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED"/>\n'
    '    <uses-permission android:name="android.permission.VIBRATE"/>\n'
    '    <uses-permission android:name="android.permission.SCHEDULE_EXACT_ALARM"/>\n'
    '    <uses-permission android:name="android.permission.ACCESS_COARSE_LOCATION"/>\n'
)
if "POST_NOTIFICATIONS" not in m:
    m = re.sub(r"(<manifest[^>]*>\n)", r"\1" + perms, m, count=1)
receivers = (
    '        <receiver android:exported="false" '
    'android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationReceiver" />\n'
    '        <receiver android:exported="false" '
    'android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationBootReceiver">\n'
    '            <intent-filter>\n'
    '                <action android:name="android.intent.action.BOOT_COMPLETED"/>\n'
    '                <action android:name="android.intent.action.MY_PACKAGE_REPLACED"/>\n'
    '                <action android:name="android.intent.action.QUICKBOOT_POWERON" />\n'
    '                <action android:name="com.htc.intent.action.QUICKBOOT_POWERON"/>\n'
    '            </intent-filter>\n'
    '        </receiver>\n'
)
if "ScheduledNotificationReceiver" not in m:
    m = m.replace("    </application>", receivers + "    </application>", 1)
own_receiver = (
    '        <receiver android:exported="false" android:name=".RescheduleReceiver">\n'
    '            <intent-filter>\n'
    '                <action android:name="android.intent.action.BOOT_COMPLETED"/>\n'
    '                <action android:name="android.intent.action.TIMEZONE_CHANGED"/>\n'
    '                <action android:name="android.intent.action.TIME_SET"/>\n'
    '                <action android:name="android.intent.action.MY_PACKAGE_REPLACED"/>\n'
    '            </intent-filter>\n'
    '        </receiver>\n'
)
if "RescheduleReceiver" not in m:
    m = m.replace("    </application>", own_receiver + "    </application>", 1)
queries = (
    '    <queries>\n'
    '        <intent>\n'
    '            <action android:name="android.intent.action.VIEW" />\n'
    '            <data android:scheme="https" />\n'
    '        </intent>\n'
    '    </queries>\n'
)
if "<queries>" not in m:
    m = m.replace("</manifest>", queries + "</manifest>", 1)
elif 'android:scheme="https"' not in m:
    m = m.replace("<queries>", queries.strip().replace("<queries>", "<queries>", 1).replace("</queries>", "").rstrip(), 1)
manifest.write_text(m)

# ---------------- MainActivity: magnetic declination channel ----------------
main_activity = (
    "package com.aurialtech.dailydeen\n\n"
    "import android.hardware.GeomagneticField\n"
    "import io.flutter.embedding.android.FlutterActivity\n"
    "import io.flutter.embedding.engine.FlutterEngine\n"
    "import io.flutter.plugin.common.MethodChannel\n\n"
    "class MainActivity : FlutterActivity() {\n"
    "    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {\n"
    "        super.configureFlutterEngine(flutterEngine)\n"
    "        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, \"dailydeen/geo\").setMethodCallHandler { call, result ->\n"
    "            if (call.method == \"declination\") {\n"
    "                try {\n"
    "                    val lat = (call.argument<Double>(\"lat\") ?: 0.0).toFloat()\n"
    "                    val lng = (call.argument<Double>(\"lng\") ?: 0.0).toFloat()\n"
    "                    val field = GeomagneticField(lat, lng, 0f, System.currentTimeMillis())\n"
    "                    result.success(field.declination.toDouble())\n"
    "                } catch (e: Exception) {\n"
    "                    result.error(\"geo\", e.message, null)\n"
    "                }\n"
    "            } else {\n"
    "                result.notImplemented()\n"
    "            }\n"
    "        }\n"
    "    }\n"
    "}\n"
)
receiver_kt = """package com.aurialtech.dailydeen

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.os.Handler
import android.os.Looper
import io.flutter.FlutterInjector
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.embedding.engine.dart.DartExecutor
import io.flutter.plugin.common.MethodChannel

/**
 * Re-schedules reminders after reboot, time-zone change, manual clock change
 * and app update. Starts a short-lived headless Flutter engine that runs the
 * Dart entry point `backgroundReschedule` (lib/main.dart).
 */
class RescheduleReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        val pending = goAsync()
        val app = context.applicationContext
        val main = Handler(Looper.getMainLooper())
        var finished = false
        var engine: FlutterEngine? = null
        fun finish() {
            if (finished) return
            finished = true
            try { engine?.destroy() } catch (ignored: Exception) {}
            try { pending.finish() } catch (ignored: Exception) {}
        }
        main.post {
            try {
                val loader = FlutterInjector.instance().flutterLoader()
                loader.startInitialization(app)
                loader.ensureInitializationComplete(app, null)
                val e = FlutterEngine(app)
                engine = e
                MethodChannel(e.dartExecutor.binaryMessenger, "dailydeen/bg").setMethodCallHandler { call, result ->
                    result.success(null)
                    if (call.method == "done") main.post { finish() }
                }
                e.dartExecutor.executeDartEntrypoint(
                    DartExecutor.DartEntrypoint(loader.findAppBundlePath(), "backgroundReschedule"),
                    listOf(intent.action ?: "")
                )
                // Safety net: broadcasts may only run for a few seconds.
                main.postDelayed({ finish() }, 9000)
            } catch (e: Exception) {
                finish()
            }
        }
    }
}
"""

for f in (app / "src/main/kotlin").rglob("MainActivity.kt"):
    f.write_text(main_activity)
    (f.parent / "RescheduleReceiver.kt").write_text(receiver_kt)

# ---------------- green launch screen ----------------
launch = (
    '<?xml version="1.0" encoding="utf-8"?>\n'
    '<layer-list xmlns:android="http://schemas.android.com/apk/res/android">\n'
    '    <item><color android:color="#FF0B4D35" /></item>\n'
    '</layer-list>\n'
)
for folder in ("drawable", "drawable-v21"):
    f = app / "src/main/res" / folder / "launch_background.xml"
    if f.parent.exists():
        f.write_text(launch)

# ---------------- app/build.gradle(.kts) ----------------
kts = app / "build.gradle.kts"
groovy = app / "build.gradle"
if kts.exists():
    g = kts.read_text()
    if "isCoreLibraryDesugaringEnabled" not in g:
        g, n = re.subn(r"compileOptions \{", "compileOptions {\n        isCoreLibraryDesugaringEnabled = true", g, count=1)
        assert n == 1, "compileOptions not found"
    if "desugar_jdk_libs" not in g:
        g += '\ndependencies {\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.5")\n}\n'
    if "keystoreProperties" not in g:
        header = (
            "import java.util.Properties\n"
            "import java.io.FileInputStream\n\n"
        )
        loader = (
            'val keystoreProperties = Properties()\n'
            'val keystorePropertiesFile = rootProject.file("key.properties")\n'
            'if (keystorePropertiesFile.exists()) {\n'
            '    keystoreProperties.load(FileInputStream(keystorePropertiesFile))\n'
            '}\n\n'
        )
        g = header + g
        g, n = re.subn(r"\nandroid \{", "\n" + loader + "android {", g, count=1)
        assert n == 1, "android block not found"
        signing = (
            "    signingConfigs {\n"
            '        create("release") {\n'
            "            if (keystorePropertiesFile.exists()) {\n"
            '                keyAlias = keystoreProperties["keyAlias"] as String\n'
            '                keyPassword = keystoreProperties["keyPassword"] as String\n'
            '                storeFile = file(keystoreProperties["storeFile"] as String)\n'
            '                storePassword = keystoreProperties["storePassword"] as String\n'
            "            }\n"
            "        }\n"
            "    }\n\n"
            "    buildTypes {"
        )
        g, n = re.subn(r"    buildTypes \{", signing, g, count=1)
        assert n == 1, "buildTypes not found"
        g, n = re.subn(
            r'signingConfig = signingConfigs\.getByName\("debug"\)',
            'signingConfig = if (keystorePropertiesFile.exists()) signingConfigs.getByName("release") '
            'else signingConfigs.getByName("debug")',
            g,
            count=1,
        )
        assert n == 1, "debug signingConfig line not found"
    kts.write_text(g)
elif groovy.exists():
    sys.exit("Groovy build.gradle not supported by this patcher")
else:
    sys.exit("No app build.gradle found")

print("Android project patched OK")
